using System.ComponentModel.DataAnnotations;
namespace StudentAccommodationSystem.Models;
public class Review { public int Id { get; set; } public int StudentProfileId { get; set; } public int PropertyId { get; set; } [Range(1,5)] public int Rating { get; set; } [StringLength(1000)] public string? Comment { get; set; } public bool IsApproved { get; set; } = true; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public StudentProfile Student { get; set; } = null!; public Property Property { get; set; } = null!; }
public class Notification { public int Id { get; set; } public string UserId { get; set; } = ""; [Required] public string Message { get; set; } = ""; public string? Url { get; set; } public bool IsRead { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public ApplicationUser User { get; set; } = null!; }
public class MessageThread { public int Id { get; set; } public string Subject { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public ICollection<Message> Messages { get; set; } = new List<Message>(); }
public class Message { public int Id { get; set; } public int MessageThreadId { get; set; } public string SenderId { get; set; } = ""; public string RecipientId { get; set; } = ""; [Required, StringLength(3000)] public string Body { get; set; } = ""; public DateTime SentAt { get; set; } = DateTime.UtcNow; public bool IsRead { get; set; } public MessageThread Thread { get; set; } = null!; public ApplicationUser Sender { get; set; } = null!; }
